input.new_string:
if locks, ok := snapshot.Payload["locks"].(map[string]any); ok {
	if writeLock, ok := locks["write"].(map[string]any); ok {
		lockState, _ := writeLock["state"].(string)
		switch lockState {
		case "unsafe", "unavailable":
			// A path problem, not a contention question: do not probe.
			add("write_lock", "error", lockState+"; read-only inspection does not probe-acquire the lock")
		default:
			// The lock FILE is created with O_CREATE and never unlinked on
			// release, so it exists permanently after the first refresh.
			// Reading its presence alone reports present_unproven forever
			// and cannot tell a free lock from a stuck one, which is the
			// only thing this check is for. `memory status` stays read-only
			// by contract; doctor is an explicit diagnostic, so it probes
			// with a short timeout the way it did before, and releases
			// immediately.
			if unlock, lerr := acquireBrainWriteLockTimeout(brainDir, 250*time.Millisecond); lerr == nil {
				unlock()
				add("write_lock", "ok", "free (probe-acquired and released)")
			} else {
				add("write_lock", "warn", "held or unavailable (normal during a refresh; persistent means a stuck refresh): "+lerr.Error())
			}
		}
	}
}

