		fakeCommandKey("git", "cat-file", "-p", v1OriginRef+":"+goodPath): {stdout: "good transcript\n"},
	}}
	branchDirs := buildBranchDirectories(sessions, "main")
	outputDir := t.TempDir()
	if err := ensureExportDirectories(outputDir, branchDirs); err != nil {
		t.Fatal(err)
	}
